# DK VSS.  Vester Sottrup - Skelde
#
let vs = path("d3.dk.vss");

with detail = 4, railway = :first :pax :removed {
    # point.dk.Vester-Sottrup  dk.SBT

    with link = "line.dk.VSS" {
        track(:lor,
                vs[:vso.ys - 0.1dl, :vso.ys] >> 1mo
            ..  vs[:vso.xs + 1mo, :vso.xs + 1.1mo]
        );
        track(vs[:vso.xs + 1mo, :ste - 0.49sw]);
    }

    with link = "point.dk.Stenderup", railway = :station {
        track(vs[:ste - 0.5sw, :ste + 0.5sw]);
        marker(:left :de.hp, vs[:ste] << 0.5mt);
        station(:right, vs[:ste] << 0.5mt << 1sh + (1.7dt, 1.7dt),
            "Stenderup", "VSS: 1,7"
        );
    }

    with link = "line.dk.VSS" {
        track(vs[:ste + 0.49sw, :nyb - 0.49sw]);
    }

    with link = "point.dk.Nybøl", railway = :station {
        track(vs[:nyb - 0.5sw, :nyb + 0.5sw]);
        marker(:right :de.bf, vs[:nyb] >> 0.5mt);
        station(:left, vs[:nyb] >> 0.5mt >> 1sh + (-1.5dt, 1.3dt),
            span(:former, "Nübel"),
            "Nybøl",
            "VSS: 3,1"
        );
    }

    with link = "line.dk.VSS" {
        track(vs[:nyb + 0.49sw, :sko - 0.49sw]);
    }

    with link = "point.dk.Skodsbøl-Sønderjylland", railway = :station {
        track(vs[:sko - 0.5sw, :sko + 0.5sw]);
        marker(:left :de.bf, vs[:sko] << 0.5mt);
        station(:right, vs[:sko] << 0.5mt << 1sh + (2dt, 1.5dt),
            span(:former, "Schottsbüll"),
            "Skodsbøl",
            "VSS: 6,3"
        );
    }

    with link = "line.dk.VSS" {
        track(vs[:sko + 0.49sw, :bro - 0.49sw]);
    }

    with link = "point.dk.Broager", railway = :station {
        track(vs[:bro - 0.5sw, :bro + 0.5sw]);
        marker(:left :de.bf, vs[:bro] << 0.5mt);
        station(:top, vs[:bro] << 0.5mt << 1sh + (0.7dt, -0.7dt),
            span(:former, "Broacker"),
            "Broager",
            "VSS: 8,2"
        );
    }

    with link = "line.dk.VSS" {
        track(vs[:bro + 0.49sw, :dyn - 0.49sw]);
    }

    with link = "point.dk.Dynt", railway = :station {
        track(vs[:dyn - 0.5sw, :dyn + 0.5sw]);
        marker(:right :de.bf, vs[:dyn] >> 0.5mt);
        station(:left:right_align, vs[:dyn] >> 0.5mt >> 1sh + (-2.3dt, 1.8dt),
            span(:former, "Dünth"),
            "Dynt",
            "VSS: 10,0"
        );
    }

    with link = "line.dk.VSS" {
        track(vs[:dyn + 0.49sw, :ske - 0.49sw]);
    }

    with link = "point.dk.Skelde", railway = :station {
        track(vs[:ske - 0.5sw, :ske.f]);
        marker(:right :de.bf, vs[:ske] >> 0.5mt);
        station(:right, vs[:ske] << 0.5mt + (2.3dt, 0.8dt),
            span(:former, "Schelde"),
            span(:bold, "Skelde"),
            "VSS: 12,4"
        );
    }

}

